import js from "@eslint/js";
import tsParser from "@typescript-eslint/parser";

export default [
  js.configs.recommended,
  {
    // `src/proto/**` is machine-generated by `npm run generate:proto` and
    // carries its own `/* eslint-disable */` banner. Linting it produces
    // findings nobody may act on (edits are overwritten on every
    // regeneration), so it is excluded here rather than tolerated as
    // permanent warning noise. It is still TYPE-checked: tsconfig includes it.
    ignores: ["dist/**", "src/proto/**"],
  },
  {
    files: ["src/**/*.ts"],
    languageOptions: {
      ecmaVersion: "latest",
      parser: tsParser,
      sourceType: "module",
    },
    rules: {
      "no-empty": "error",
      "no-throw-literal": "error",
      "no-redeclare": "off",
      "no-undef": "off",
      "no-unused-vars": "off",
    },
  },
];
